function updateStudentSummary(){var rows=studentFiltered(),totalDuration=rows.reduce(function(a,r){return a+n(r.actualDurationSeconds)},0),totalWords=rows.reduce(function(a,r){return a+n(r.totalChildWords)},0);setText('sumSessions',rows.length);setText('sumDuration',secText(totalDuration));setText('sumAvgDuration',secText(avg(rows.map(function(r){return r.actualDurationSeconds}))));setText('sumTurns',avg(rows.map(function(r){return r.totalTurns})).toFixed(1));setText('sumTotalWords',totalWords);setText('sumWords',avg(rows.map(function(r){return r.totalChildWords})).toFixed(1));setText('sumThemes',new Set(rows.map(function(r){return r.topic}).filter(Boolean)).size+'種');setText('sumPartners',new Set(rows.map(function(r){return r.aiStudentId}).filter(Boolean)).size+'人');function pct(k){return ratingPct(rows,k,false)+'%'}setText('r1avg',rows.length?pct('conveyedIdeas'):'—');setText('r2avg',rows.length?pct('understoodPartner'):'—');setText('r3avg',rows.length?pct('noticedLanguageCulture'):'—');var cumulative=0;drawChart('sumDurationChart',[{name:'累積対話時間（分）',points:rows.map(function(r,i){cumulative+=n(r.actualDurationSeconds)/60;return{k:dateOf(r)+'-'+String(i+1).padStart(2,'0'),v:Math.round(cumulative*10)/10}})}]);drawChart('sumWordsChart',[{name:'語数',points:rows.map(function(r,i){return{k:dateOf(r)+'-'+String(i+1).padStart(2,'0'),v:n(r.totalChildWords)}})}]);$('summaryRows').innerHTML=rows.map(function(r){return '<tr><td>'+esc(r.sessionId)+'</td><td>'+esc(fmtDate(r))+'</td><td>'+esc(topicText(r.topic||''))+'</td><td>'+esc(r.aiStudentId||'—')+'</td><td>'+secText(r.actualDurationSeconds)+'</td><td>'+n(r.totalTurns)+'</td><td>'+n(r.totalChildWords)+'</td><td><button class="link session-open" data-id="'+esc(r.sessionId)+'">詳細を見る</button></td></tr>'}).join('');document.querySelectorAll('.session-open').forEach(function(b){b.addEventListener('click',function(){openSession(b.dataset.id)})})}
function ratingLabel(v){v=n(v);return v>=5?'できた':v>=3?'少しできた':v>0?'次はがんばる':'—'}
function openSession(id){var r=teacherSessions.find(function(x){return x.sessionId===id});if(!r)return;setText('detailStudentCrumb',currentTeacherStudent);setText('detailSessionCrumb',id);$('detailHead').innerHTML=[['日付',fmtDate(r)],['AI留学生',r.aiStudentId||'—'],['テーマ',topicText(r.topic||'')],['対話時間',secText(r.actualDurationSeconds)],['ターン数',n(r.totalTurns)+'回'],['発話語数',n(r.totalChildWords)+'語'],['語彙数',n(r.uniqueVocabularyCount)+'語'],['通算回',n(r.lifetimeSessionNumber)+'回']].map(function(x){return '<div class="detail-box"><span>'+esc(x[0])+'</span><b>'+esc(x[1])+'</b></div>'}).join('');var ref=r.reflection||{};$('detailReflection').innerHTML='<b>振り返りの回答</b>'+[['自分の考えを伝える',ref.conveyedIdeas],['相手の話を聞いて分かる',ref.understoodPartner],['新しい言葉や文化に気づいた',ref.noticedLanguageCulture]].map(function(x){return '<div class="reflection-row"><span>'+x[0]+'</span><b>'+ratingLabel(x[1])+'</b></div>'}).join('');var h=Array.isArray(r.history)?r.history:[];$('detailLog').innerHTML='<div><b>児童</b>'+h.filter(function(m){return m.sender==='child'}).map(function(m){return '<div class="bubble child">'+esc(m.englishText||'')+'</div>'}).join('')+'</div><div><b>AI留学生</b>'+h.filter(function(m){return m.sender==='ai'}).map(function(m){return '<div class="bubble ai">'+esc(m.englishText||'')+'</div>'}).join('')+'</div>';show('sessionDetail')}
