function researchFiltered(start,end,scope){return researchData.filter(function(r){return within(r,start,end)&&classMatches(r.class_id,scope)})}
function researchMissingRow(r){return String(r.data_quality_flag||'')!=='complete'||!r.research_id||!r.session_id||!r.local_date||r.total_turns===''||r.total_child_words===''||r.actual_duration_seconds===''}
function researchMetricValues(rows,metric){return rows.map(function(r){return metricValue(r,metric,true)}).filter(Number.isFinite)}
function researchStatsHtml(rows,metric){var v=researchMetricValues(rows,metric);var mean=avg(v),med=median(v),sd=stdDev(v);return [['n',v.length],['平均',mean.toFixed(1)],['中央値',med.toFixed(1)],['SD',sd.toFixed(1)],['最小',minVal(v).toFixed(1)],['最大',maxVal(v).toFixed(1)]].map(function(x){return '<div class="stat-chip">'+x[0]+'<b>'+x[1]+'</b></div>'}).join('')}
function stageSummaryHtml(rows){var groups={'1回目':[],'2〜3回目':[],'4〜6回目':[],'7回目以上':[]};rows.forEach(function(r){var k=n(r.lifetime_session_number);var g=k<=1?'1回目':k<=3?'2〜3回目':k<=6?'4〜6回目':'7回目以上';groups[g].push(r)});return Object.keys(groups).map(function(g){var rs=groups[g];return '<div class="summary-row"><span><b>'+g+'</b><br><span class="muted">n='+rs.length+'</span></span><b>'+median(rs.map(function(r){return r.total_child_words})).toFixed(1)+'語</b></div>'}).join('')}
function updateResearchDashboard(){var s=$('researchStart').value,e=$('researchEnd').value,scope=$('researchDashboardClass').value,rows=researchFiltered(s,e,scope),ids=new Set(rows.map(function(r){return r.research_id}).filter(Boolean)),missing=rows.filter(researchMissingRow),complete=rows.length-missing.length,words=rows.map(function(r){return n(r.total_child_words)});setText('researchStudents',ids.size);setText('researchSessions',rows.length);setText('researchCompleteCases',complete);setText('researchMissingRate',(rows.length?Math.round(missing.length/rows.length*100):0)+'%');setText('researchMedianWords',median(words).toFixed(1));setText('researchSdWords',stdDev(words).toFixed(1));setText('researchAvgTurns',avg(rows.map(function(r){return r.total_turns})).toFixed(1));setText('researchAvgDuration',secText(avg(rows.map(function(r){return r.actual_duration_seconds}))));var ds=rows.map(dateOf).filter(Boolean).sort(),classes=scopeClasses(scope,rows),metric=$('researchMetric').value,lab=metric==='turns'?'ターン数':metric==='duration'?'対話時間（分）':metric==='reflection'?'振り返り平均':metric==='sessions'?'セッション回数':'発話語数';setText('researchPeriod',ds.length?ds[0]+'〜'+ds[ds.length-1]:'—');setText('researchChartTitle','匿名化データ：'+lab+'の推移');setText('researchConditionSummary','収集期間: '+(ds.length?ds[0]+'〜'+ds[ds.length-1]:'—')+' ／ 対象: '+(scope==='all'?'すべて':scope==='grade5'?'5年':scope==='grade6'?'6年':scope)+' ／ '+(researchAgg==='week'?'週別':'月別')+' ／ '+lab);$('researchLegend').innerHTML=classes.map(function(x,i){return '<span style="color:'+palette[i%palette.length]+'">'+esc(x)+'</span>'}).join('');drawChart('researchChart',aggregate(rows,classes,metric,researchAgg,true));$('researchDescriptiveStats').innerHTML=researchStatsHtml(rows,metric);$('researchStageSummary').innerHTML=stageSummaryHtml(rows);$('researchUsageSummary').innerHTML=usageSummaryHtml(rows)}
function researchGroups(){var s=$('r3Start').value,e=$('r3End').value,cls=$('researchClass').value,grade=$('researchGrade').value,q=$('researchSearch').value.trim().toUpperCase(),complete=$('researchCompleteOnly').checked,rows=researchFiltered(s,e,cls),map={};rows.forEach(function(r){if(grade!=='all'&&canonClass(r.class_id||'').charAt(0)!==grade)return;if(q&&String(r.research_id||'').toUpperCase().indexOf(q)<0)return;if(complete&&researchMissingRow(r))return;(map[r.research_id]||(map[r.research_id]=[])).push(r)});return map}
function renderResearchList(){var map=researchGroups();$('researchRows').innerHTML=Object.keys(map).sort().map(function(id){var rows=map[id],miss=rows.filter(researchMissingRow).length,complete=rows.length-miss,last=rows.map(dateOf).sort().pop()||'—',totalDuration=rows.reduce(function(a,r){return a+n(r.actual_duration_seconds)},0),med=median(rows.map(function(r){return r.total_child_words}));return '<tr><td><button class="link research-open" data-id="'+esc(id)+'">'+esc(id)+'</button></td><td>'+esc(rowClass(rows[0]))+'</td><td>'+rows.length+'</td><td>'+complete+'</td><td>'+(rows.length?Math.round(miss/rows.length*100):0)+'%</td><td>'+secText(totalDuration)+'</td><td>'+avg(rows.map(function(r){return r.total_turns})).toFixed(1)+'</td><td>'+avg(rows.map(function(r){return r.total_child_words})).toFixed(1)+'</td><td>'+med.toFixed(1)+'</td><td>'+esc(last)+'</td></tr>'}).join('');document.querySelectorAll('.research-open').forEach(function(b){b.addEventListener('click',function(){openResearch(b.dataset.id)})})}
function openResearch(id){currentResearchId=id;setText('researchSummaryCrumb',id);setText('researchSummaryTitle',id+'の個人内縦断データ');$('r4Start').value=$('r3Start').value;$('r4End').value=$('r3End').value;show('researchSummary');updateResearchSummary()}
function currentResearchRows(){return researchData.filter(function(r){return r.research_id===currentResearchId&&within(r,$('r4Start').value,$('r4End').value)}).sort(function(a,b){var ak=n(a.lifetime_session_number),bk=n(b.lifetime_session_number);return ak-bk||dateOf(a).localeCompare(dateOf(b))})}
function deltaText(a,b,suffix){if(a==null||b==null)return'—';var d=n(b)-n(a);return(d>=0?'+':'')+d.toFixed(1)+(suffix||'')}
function updateResearchSummary(){var rows=currentResearchRows(),totalDuration=rows.reduce(function(a,r){return a+n(r.actual_duration_seconds)},0),first=rows[0],last=rows[rows.length-1];setText('r4Sessions',rows.length+'件');setText('r4TotalDuration',secText(totalDuration));setText('r4Duration',secText(avg(rows.map(function(r){return r.actual_duration_seconds}))));setText('r4Turns',avg(rows.map(function(r){return r.total_turns})).toFixed(1));setText('r4Words',avg(rows.map(function(r){return r.total_child_words})).toFixed(1));setText('r4DeltaWords',rows.length>1?deltaText(first.total_child_words,last.total_child_words,'語'):'—');setText('r4DeltaTurns',rows.length>1?deltaText(first.total_turns,last.total_turns,'回'):'—');setText('r4DeltaReflection',rows.length>1?deltaText(reflectionValue(first),reflectionValue(last),''):'—');drawChart('r4TurnChart',[{name:'ターン',points:rows.map(function(r,i){return{k:dateOf(r)+'-'+String(i+1).padStart(2,'0'),v:n(r.total_turns)}})}]);drawChart('r4WordChart',[{name:'語数',points:rows.map(function(r,i){return{k:dateOf(r)+'-'+String(i+1).padStart(2,'0'),v:n(r.total_child_words)}})}]);drawChart('r4ReflectionChart',[{name:'振り返り',points:rows.map(function(r,i){return{k:dateOf(r)+'-'+String(i+1).padStart(2,'0'),v:reflectionValue(r)}})}]);$('r4Rows').innerHTML=rows.map(function(r){return '<tr><td>'+esc(r.session_id)+'</td><td>'+n(r.lifetime_session_number)+'</td><td>'+esc(dateOf(r))+'</td><td>'+esc(topicText(r.topic||''))+'</td><td>'+secText(r.actual_duration_seconds)+'</td><td>'+n(r.total_turns)+'</td><td>'+n(r.total_child_words)+'</td><td>'+(researchMissingRow(r)?'あり':'なし')+'</td><td><button class="link r5-open" data-id="'+esc(r.session_id)+'">'+esc(r.session_id)+'</button></td></tr>'}).join('');document.querySelectorAll('.r5-open').forEach(function(b){b.addEventListener('click',function(){openResearchSession(b.dataset.id)})})}
function openResearchSession(id){currentResearchSession=id;var r=researchData.find(function(x){return x.session_id===id&&x.research_id===currentResearchId});if(!r)return;setText('r5ResearchCrumb',currentResearchId);setText('r5SessionCrumb',id);$('r5Head').innerHTML=[['research_id',r.research_id],['class_id',r.class_id],['通算回',r.lifetime_session_number],['記録日',r.local_date],['テーマ',topicText(r.topic||'')],['AI留学生',r.ai_student_id],['対話時間',secText(r.actual_duration_seconds)],['ターン数',r.total_turns+'回'],['発話語数',r.total_child_words+'語'],['語彙数',r.unique_vocabulary_count+'語']].map(function(x){return '<div class="detail-box"><span>'+esc(x[0])+'</span><b>'+esc(x[1]||'—')+'</b></div>'}).join('');$('r5Reflection').innerHTML='<b>振り返り（3項目）</b>'+[['自分の考えを伝える',r.reflection_conveyed_ideas],['相手の話を聞いて分かる',r.reflection_understood_partner],['新しい言葉や文化に気づいた',r.reflection_noticed_language_culture]].map(function(x){return '<div class="reflection-row"><span>'+x[0]+'</span><b>'+ratingLabel(x[1])+'</b></div>'}).join('');$('r5AnonLog').innerHTML='<div class="bubble child">● 児童発話：匿名化済み（本文非表示）</div><div class="bubble ai">● AI留学生応答：匿名化指標のみ</div>';show('researchSession')}
function rowStatus(r,dups){var missing=researchMissingRow(r),review=n(r.total_turns)===0||n(r.total_child_words)===0;if(dups[r.session_id]>1)return['重複','同一session_id'];if(missing)return['欠損','必須指標欠損'];if(review)return['要確認','ターン数または発話語数が0'];return['正常','—']}
function renderQuality(){var rows=researchFiltered($('r6Start').value,$('r6End').value,$('r6Class').value),rid=$('r6Research').value;if(rid&&rid!=='all')rows=rows.filter(function(r){return r.research_id===rid});if($('r6CompleteOnly').checked)rows=rows.filter(function(r){return !researchMissingRow(r)});var dups={};rows.forEach(function(r){dups[r.session_id]=(dups[r.session_id]||0)+1});var states=rows.map(function(r){return rowStatus(r,dups)});setText('qNormal',states.filter(function(s){return s[0]==='正常'}).length+'件');setText('qMissing',states.filter(function(s){return s[0]==='欠損'}).length+'件');setText('qDuplicate',states.filter(function(s){return s[0]==='重複'}).length+'件');setText('qReview',states.filter(function(s){return s[0]==='要確認'}).length+'件');$('qualityRows').innerHTML=rows.slice(0,5).map(function(r){var s=rowStatus(r,dups);return '<tr><td>'+esc(r.session_id)+'</td><td>'+s[0]+'</td><td>'+s[1]+'</td></tr>'}).join('');return rows}
function toCsv(rows){if(!rows.length)return'';var h=Object.keys(rows[0]);function q(v){return '\"'+String(v==null?'':v).replace(/\"/g,'\"\"')+'\"'}return h.map(q).join(',')+String.fromCharCode(10)+rows.map(function(r){return h.map(function(k){return q(r[k])}).join(',')}).join(String.fromCharCode(10))}
function downloadRows(rows,name){var blob=new Blob(['\uFEFF'+toCsv(rows)],{type:'text/csv;charset=utf-8'});var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(a.href)},500)}
function addExportHistory(rows,name){exportHistory.unshift({at:new Date().toLocaleString('ja-JP'),cond:($('r6Class').value||'all')+' / '+($('r6Research').value||'all'),rows:rows.length,name:name});$('exportRows').innerHTML=exportHistory.map(function(x){return '<tr><td>'+esc(x.at)+'</td><td>'+esc(x.cond)+'</td><td>'+x.rows+'</td><td>'+esc(x.name)+'</td></tr>'}).join('')}
async function downloadResearchDataset(dataset){var sessionRows=renderQuality(),allowed=new Set(sessionRows.map(function(r){return r.session_id})),rows;if(dataset==='sessions'){rows=sessionRows}else{var resp=await fetch('/api/management/research.csv?dataset='+encodeURIComponent(dataset));if(!resp.ok)throw new Error('RESEARCH_DATA_UNAVAILABLE');rows=csvParse(await resp.text()).filter(function(r){return allowed.has(r.session_id)})}var name='research_'+dataset+'_'+new Date().toISOString().slice(0,10).replace(/-/g,'')+'.csv';downloadRows(rows,name);addExportHistory(rows,name)}
async function downloadResearchBundle(){var q=new URLSearchParams();if($('r6Start').value)q.set('start',$('r6Start').value);if($('r6End').value)q.set('end',$('r6End').value);if($('r6Class').value&&$('r6Class').value!=='all')q.set('classId',$('r6Class').value);if($('r6Research').value&&$('r6Research').value!=='all')q.set('researchId',$('r6Research').value);if($('r6CompleteOnly').checked)q.set('completeOnly','1');var r=await fetch('/api/management/research.bundle.zip?'+q.toString());if(!r.ok)throw new Error('RESEARCH_BUNDLE_UNAVAILABLE');var blob=await r.blob(),a=document.createElement('a'),name='research_bundle_'+new Date().toISOString().slice(0,10).replace(/-/g,'')+'.zip';a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(a.href)},500);addExportHistory(renderQuality(),name)}
async function loadTeacher(){var a=await Promise.all([fetch('/api/management/sessions'),fetch('/api/management/student-codes')]),sd=await a[0].json(),cd=await a[1].json();if(!a[0].ok||!sd.success)throw new Error(sd.error||'DATA_ERROR');if(!a[1].ok||!cd.success)throw new Error(cd.error||'CODE_ERROR');studentRecords=(Array.isArray(cd.students)?cd.students:[]).map(function(rec){rec.classId=canonClass(rec.classId||'');return rec});var classByStudent={};studentRecords.forEach(function(rec){classByStudent[rec.studentId]=rec.classId});teacherSessions=(Array.isArray(sd.sessions)?sd.sessions:[]).map(function(row){row.classId=canonClass(row.classId||classByStudent[row.studentId]||'');return row});fillSchoolClassSelect('teacherClass','すべて');fillSchoolClassSelect('listClass','すべて');fillSchoolClassSelect('newClass','');initDates('teacher',teacherSessions);initDates('list',teacherSessions);$('listStart').value=$('teacherStart').value;$('listEnd').value=$('teacherEnd').value;updateTeacherDashboard();teacherStudentRows();renderCodes()}
async function loadResearch(){var r=await fetch('/api/management/research.csv');if(!r.ok)throw new Error('RESEARCH_DATA_UNAVAILABLE');researchData=csvParse(await r.text());fillResearchScopeSelect('researchDashboardClass');$('researchDashboardClass').value='all';fillSchoolClassSelect('researchClass','すべて');fillSchoolClassSelect('r6Class','すべて');initDates('research',researchData);initDates('r3',researchData);initDates('r6',researchData);$('r3Start').value=$('researchStart').value;$('r3End').value=$('researchEnd').value;$('r6Start').value=$('researchStart').value;$('r6End').value=$('researchEnd').value;var ids=Array.from(new Set(researchData.map(function(x){return x.research_id}).filter(Boolean))).sort();fillSelect('r6Research',ids,'すべて');updateResearchDashboard();renderResearchList();renderQuality()}
function setRoleUi(){var teacher=role==='teacher';['teacherDashboardBtn','studentListBtn','codeBtn'].forEach(function(id){$(id).style.display=teacher?'inline-block':'none'});['researchDashboardBtn','researchListBtn','researchQualityBtn'].forEach(function(id){$(id).style.display=teacher?'none':'inline-block'});setText('modeLabel',teacher?'教師用：授業支援':'研究者用：匿名化分析');show(teacher?'teacherDashboard':'researchDashboard')}
async function doLogin(){setText('msg','確認中…');var r=await fetch('/api/management/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('u').value,password:$('p').value})}),d=await r.json();if(!r.ok||!d.success){$('msg').className='error';setText('msg','ログインできません。IDとパスワードを確認してください。');return}role=d.role;$('login').style.display='none';$('panel').style.display='block';var me=await fetch('/api/management/me'),md=await me.json();setText('who',(md.user&&md.user.username?md.user.username:$('u').value)+' ('+role+')');setRoleUi();try{if(role==='teacher')await loadTeacher();else await loadResearch()}catch(e){alert(String(e.message||e))}}
